-- Import des recettes du carnet d’origine (à exécuter une fois, après supabase-schema.sql).
-- Elles sont rattachées au premier compte de la table editeurs.

insert into public.recettes (id, user_id, titre, sous_titre, date, tags, art, infos, histoire, ingredients, etapes, faq, lien)
select $r$cookies-pepites-chocolat$r$, e.user_id, $r$Cookies aux pépites de chocolat$r$, $r$C'est le classique indémodable qui nous met l'eau à la bouche. Ils ont le pouvoir de réconforter et de ravir nos papilles à chaque bouchée.$r$, $r$2026-09-27$r$::date, array[$r$Dessert$r$, $r$Végan$r$, $r$30 min$r$, $r$Sans lactose$r$]::text[], null,
  $r$[["Préparation","15 minutes"],["Cuisson","11 minutes"],["Méthode de cuisson","Four"],["Portions","8 cookies"]]$r$::jsonb, array[]::text[], array[$r$60 g de sucre$r$, $r$100 g de sucre brun$r$, $r$100 g d’huile de coco fondue$r$, $r$80 ml d’aquafaba (le liquide de cuisson des pois chiches)$r$, $r$250 g de farine de blé$r$, $r$1 c. de levure chimique$r$, $r$100 g de chocolat en tablette$r$, $r$Gros sel$r$]::text[], array[$r$Préchauffer le four à 180 °C et hacher grossièrement la tablette de chocolat en gros morceaux.$r$, $r$Dans un grand saladier, fouetter l’aquafaba, le sucre, le sucre roux et l’huile de coco fondue.$r$, $r$Ajouter la farine et la levure chimique. Bien mélanger jusqu’à former une pâte, puis ajouter les morceaux de chocolat. Réserver 15 à 30 minutes au frigo pour laisser la pâte se raffermir.$r$, $r$Former des petites boules bien hautes et les déposer sur la plaque du four recouverte d’un tapis de cuisson ou de papier sulfurisé. Enfourner 11 minutes.$r$, $r$À la sortie du four, saupoudrer de gros sel et laisser complètement refroidir avant de déguster.$r$]::text[],
  $r$[{"question":"Comment réussir cette recette sans gluten ?","reponse":"Utilisez la même quantité de farine, et privilégiez un mélange de farine sans gluten à base de farines de riz, maïs et pomme de terre comme ce produit, avec lequel ce sera un succès."},{"question":"Comment préparer soi-même un mix de farine sans gluten ?","reponse":"Il existe plusieurs façons de préparer soi-même un mix de farines sans gluten, voici ma recette préférée en cliquant ici. Avec ce mélange, je réussis à tous les coups mes recettes sans gluten, et il remplace très bien une farine classique !"},{"question":"Comment conserver ces cookies ?","reponse":"Ces cookies se conservent jusqu’à cinq jours à température ambiante dans une boîte hermétique. Assurez-vous de les conserver dans un endroit frais et sec pour préserver leur fraîcheur et leur texture."}]$r$::jsonb, null
from (select user_id from public.editeurs limit 1) e
union all
select $r$club-sandwich-thon-mayo-vegetarien$r$, e.user_id, $r$Club sandwich comme un thon mayo !$r$, $r$Avec une garniture alternative gourmande, fraîche et riche en saveurs.$r$, $r$2026-09-28$r$::date, array[$r$Plat$r$, $r$Végétarien$r$, $r$Presque rien$r$, $r$Printemps$r$, $r$Été$r$, $r$10 min$r$]::text[], $r$feuillage$r$,
  $r$[["Préparation","5 min"],["Cuisson","5 min"],["Portions","2 sandwiches"]]$r$::jsonb, array[$r$Inspirée d’une recette américaine de « Smashed Chickpea Salad Sandwich », cette version revisite le célèbre sandwich thon-mayo en version végétarienne.$r$, $r$L’autrice a adapté la recette avec des haricots blancs à la place des pois chiches et a ajouté citron et câpres pour retrouver les saveurs caractéristiques du thon-mayo.$r$]::text[], array[$r$250 g de haricots blancs ou pois chiches égouttés$r$, $r$2 cuillères à soupe de mayonnaise$r$, $r$1 cuillère à café de moutarde$r$, $r$1 échalote hachée$r$, $r$1 cuillère à soupe de jus de citron$r$, $r$1 cuillère à café de câpres hachées$r$, $r$1 cuillère à café d’aneth haché$r$, $r$1 cuillère à café de cornichons à l’américaine coupés en petits morceaux$r$, $r$1 pincée de sel$r$, $r$1 pincée de poivre$r$, $r$1 pincée de piment$r$, $r$Des crudités au choix (salade, tomate, graines germées, carottes râpées, concombre...)$r$, $r$4 tranches de pain complet$r$]::text[], array[$r$Rincer et égoutter les haricots blancs ou les pois chiches.$r$, $r$Les écraser grossièrement à la fourchette ou au presse-purée en conservant quelques morceaux.$r$, $r$Ajouter la mayonnaise, la moutarde, l’échalote, le jus de citron, les câpres, l’aneth et les cornichons.$r$, $r$Mélanger puis ajuster l’assaisonnement avec le sel, le poivre et le piment.$r$, $r$Faire griller les tranches de pain complet.$r$, $r$Garnir le pain avec le mélange et les crudités de votre choix.$r$, $r$Refermer les sandwiches et servir immédiatement.$r$]::text[],
  $r$[{"question":"Puis-je utiliser des pois chiches à la place des haricots blancs ?","reponse":"Oui, la recette fonctionne parfaitement avec des pois chiches et se rapproche davantage de la version originale américaine."},{"question":"Peut-on préparer la garniture à l’avance ?","reponse":"Oui, le mélange peut être préparé plusieurs heures à l’avance et gagne même en saveur après repos au réfrigérateur."}]$r$::jsonb, null
from (select user_id from public.editeurs limit 1) e
on conflict (id) do nothing;
